#!/usr/bin/env python3
"""Checks the Kubernetes manifests in deploy/k8s/base (generated by deploy/k8s/gen.py).

They are not applied to a cluster here: this environment has none. What is checked is what can go wrong on paper:
  - the files match the generator (so ports and caller lists match the stack);
  - every Deployment is hardened (non-root, read-only filesystem, no privilege escalation, all capabilities dropped,
    seccomp, resource limits, three probes, at least two replicas, production mode, health listener);
  - no dev-only switch and no secret value in the environment;
  - every service has a Service, a PodDisruptionBudget, a Certificate and a NetworkPolicy, and the namespace denies
    everything by default;
  - the caller-list ConfigMaps equal the files the stack tests with;
  - images are never :latest.
It reports how many PLACEHOLDER values remain: each is a choice nobody has made yet (hosting, providers).
`--selftest` proves the checks fail when they should.
"""
import copy, glob, json, os, re, subprocess, sys
import yaml

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
BASE = os.path.join(ROOT, "deploy/k8s/base")
DEV = {"ACQUIRER", "BANK_ALLOW_SIMULATION", "DIDIT_ENVIRONMENT", "KYC_PROVIDER", "LEDGER_STORE", "PAYMENTS_ALLOW_SIMULATION",
       "POLICY_DEV_UNSIGNED", "RAILS_SIMULATION", "BACKOFFICE_AUTH", "WORKSPACE_AUTH", "BUREAU", "CARD_PROCESSOR"}
SECRETISH = re.compile(r"(KEY|SECRET|PASSWORD|TOKEN|DSN|DATABASE_URL)", re.I)
SECCOMP_EXCEPTION = {"ledger"}


def docs():
    out = []
    for f in sorted(glob.glob(os.path.join(BASE, "*.yaml"))):
        if f.endswith("kustomization.yaml"):
            continue
        for d in yaml.safe_load_all(open(f)):
            if d:
                out.append((os.path.basename(f), d))
    return out


def check_deployment(fn, d, problems):
    n = d["metadata"]["name"]
    spec = d["spec"]
    pod = spec["template"]["spec"]
    c = pod["containers"][0]
    sc, psc = c.get("securityContext", {}), pod.get("securityContext", {})
    p = lambda msg: problems.append(f"{n}: {msg}")
    if spec.get("replicas", 1) < 2: p("fewer than 2 replicas")
    if not psc.get("runAsNonRoot") or not sc.get("runAsNonRoot"): p("must run as non-root")
    if sc.get("allowPrivilegeEscalation") is not False: p("privilege escalation allowed")
    if not sc.get("readOnlyRootFilesystem"): p("root filesystem is writable")
    if sc.get("capabilities", {}).get("drop") != ["ALL"]: p("must drop all capabilities")
    seccomp = sc.get("seccompProfile", {}).get("type")
    if seccomp != "RuntimeDefault" and not (seccomp == "Unconfined" and n in SECCOMP_EXCEPTION): p(f"seccomp profile {seccomp}")
    if pod.get("automountServiceAccountToken") is not False: p("service account token is mounted")
    for probe in ("readinessProbe", "livenessProbe", "startupProbe"):
        if probe not in c: p(f"no {probe}")
    if not c.get("resources", {}).get("limits") or not c.get("resources", {}).get("requests"): p("no resource requests and limits")
    img = c["image"]
    if img.endswith(":latest") or ":" not in img.rsplit("/", 1)[-1]: p(f"image {img} is not pinned")
    env = {e["name"]: e.get("value", "") for e in c.get("env", [])}
    if env.get("FORGE_ENV") != "production": p("FORGE_ENV is not production")
    if not env.get("HEALTH_ADDR"): p("no health listener")
    for k in env:
        if k in DEV: p(f"dev-only setting {k}")
        if SECRETISH.search(k) and not k.endswith("_FILE") and not k.endswith("_ADDRESSES"): p(f"secret-like {k} given as a value, not a file")
    for e in c.get("env", []):
        if "valueFrom" in e: p(f"{e['name']} read from the cluster by reference; secrets must be mounted files")
    for k in ("TLS_CERT_FILE", "TLS_KEY_FILE", "TLS_CA_FILE"):
        if k not in env: p(f"{k} missing: production requires mutual TLS")


def check(items):
    problems = []
    kinds = {}
    for fn, d in items:
        kinds.setdefault((d["kind"], d["metadata"]["name"]), d)
    deployments = [d for (k, _), d in kinds.items() if k == "Deployment"]
    if not deployments: problems.append("no deployments")
    for d in deployments:
        n = d["metadata"]["name"]
        check_deployment(None, d, problems)
        for kind in ("Service", "PodDisruptionBudget", "NetworkPolicy", "ServiceAccount"):
            if (kind, n) not in kinds: problems.append(f"{n}: no {kind}")
        if ("Certificate", f"{n}-tls") not in kinds: problems.append(f"{n}: no Certificate")
        else:
            uris = kinds[("Certificate", f"{n}-tls")]["spec"].get("uris", [])
            if len(uris) != 1 or not uris[0].startswith("spiffe://forge/svc/svc-"): problems.append(f"{n}: certificate must name one spiffe://forge/svc/ identity")
        np = kinds.get(("NetworkPolicy", n))
        if np and set(np["spec"].get("policyTypes", [])) != {"Ingress", "Egress"}: problems.append(f"{n}: network policy must restrict ingress and egress")
        cm = kinds.get(("ConfigMap", f"{n}-callers"))
        if cm:
            c = d["spec"]["template"]["spec"]["containers"][0]
            if not any(m["mountPath"] == "/config" for m in c["volumeMounts"]): problems.append(f"{n}: caller list not mounted")
    if ("NetworkPolicy", "default-deny") not in kinds: problems.append("namespace has no default-deny policy")
    ns = kinds.get(("Namespace", "forge"))
    if not ns or ns["metadata"]["labels"].get("pod-security.kubernetes.io/enforce") != "restricted": problems.append("namespace does not enforce the restricted pod security standard")
    # The caller lists must be the ones the stack is tested with.
    for (kind, name), d in kinds.items():
        if kind == "ConfigMap" and name.endswith("-callers"):
            got = json.loads(d["data"]["callers.json"])
            files = [f for f in glob.glob(os.path.join(ROOT, "deploy/compose/config/callers/*.json")) if json.load(open(f)) == got]
            if not files: problems.append(f"{name}: matches no file in deploy/compose/config/callers")
    return problems


def placeholders():
    n = 0
    for f in glob.glob(os.path.join(BASE, "*.yaml")):
        n += len(re.findall(r"PLACEHOLDER", open(f).read()))
    return n


def selftest(items):
    def mutate(fn):
        c = copy.deepcopy(items)
        for _, d in c:
            if d["kind"] == "Deployment" and d["metadata"]["name"] == "party":
                fn(d)
        return check(c)
    cases = {
        "root": lambda d: d["spec"]["template"]["spec"]["containers"][0]["securityContext"].update(runAsNonRoot=False),
        "writable": lambda d: d["spec"]["template"]["spec"]["containers"][0]["securityContext"].update(readOnlyRootFilesystem=False),
        "latest": lambda d: d["spec"]["template"]["spec"]["containers"][0].update(image="x/party:latest"),
        "dev switch": lambda d: d["spec"]["template"]["spec"]["containers"][0]["env"].append({"name": "POLICY_DEV_UNSIGNED", "value": "true"}),
        "secret value": lambda d: d["spec"]["template"]["spec"]["containers"][0]["env"].append({"name": "PARTY_SEAL_KEY", "value": "abc"}),
        "one replica": lambda d: d["spec"].update(replicas=1),
        "no probe": lambda d: d["spec"]["template"]["spec"]["containers"][0].pop("readinessProbe"),
    }
    for name, fn in cases.items():
        if not mutate(fn):
            print(f"FAIL selftest: the check did not catch: {name}")
            sys.exit(1)
    print(f"ok   k8s checks catch {len(cases)} deliberate faults")


def main():
    r = subprocess.run([sys.executable, "-I", os.path.join(ROOT, "deploy/k8s/gen.py"), "--check"], capture_output=True, text=True)
    if r.returncode:
        print(r.stdout + r.stderr); sys.exit(1)
    items = docs()
    problems = check(items)
    for p in problems: print("FAIL", p)
    if problems: sys.exit(1)
    if "--selftest" in sys.argv: selftest(items)
    nd = sum(1 for _, d in items if d["kind"] == "Deployment")
    print(f"k8s: {nd} services, 0 problems, {placeholders()} PLACEHOLDER values still to choose")


main()
